void q_insert (Q q , Q_Msg * q_msg)
{
  if (os_irq_executing)
  	os_mbx_send_i (q->mbx , cast_q_msg_to_mbx_msg (q_msg)) ;
  else
  	os_mbx_send   (q->mbx , cast_q_msg_to_mbx_msg (q_msg)) ;
} 

